old = db.automatic_work peer = AgentRunsDB(db.db_path, client_id="replacement", reconcile_on_init=False) committed, release = threading.Event(), threading.Event() transaction = old.transaction
@contextmanager def pause_after_real_commit(): with transaction() as conn: yield conn committed.set() assert release.wait(10)
